'use client';

import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useSession } from '@/lib/auth-client';

export default function ProfilePage() {
	const router = useRouter();
	const { data: session } = useSession();

	// If not logged in, show a gentle prompt to sign in
	if (!session?.user) {
		return (
			<div className='min-h-screen flex items-center justify-center px-4 pb-10'>
				<div className='card bg-base-100 shadow-xl max-w-md w-full'>
					<div className='card-body space-y-4'>
						<h1 className='card-title text-2xl'>Profile</h1>
						<p className='text-sm text-base-content/70'>
							You need to be signed in to view your profile.
						</p>
						<div className='flex gap-2 justify-end'>
							<Link
								href={`/login?callbackURL=${encodeURIComponent('/profile')}`}
								className='btn btn-primary btn-sm'>
								Sign in
							</Link>
							<Link href='/' className='btn btn-ghost btn-sm'>
								Back home
							</Link>
						</div>
					</div>
				</div>
			</div>
		);
	}

	const { user } = session;
	const displayName = user.name || user.email?.split('@')[0] || 'Your name';
	const initials =
		user.name
			?.split(' ')
			.map((part) => part[0])
			.join('')
			.toUpperCase() ??
		user.email?.[0]?.toUpperCase() ??
		'?';

	return (
		<div className='min-h-screen flex justify-center px-4 pb-10 '>
			<div className='max-w-5xl mx-auto py-10 px-4 pb-32'>
				<section className='pt-10'>
					<h1 className='text-3xl font-bold mb-6'>My Profile</h1>
				</section>

				<div className='card bg-base-100 shadow-xl'>
					<div className='card-body space-y-6'>
						{/* Top row: avatar + basic info */}
						<div className='flex flex-col gap-4 md:flex-row md:items-center md:justify-between'>
							<div className='flex items-center gap-4'>
								<div className='avatar'>
									<div className='w-16 rounded-full bg-primary text-primary-content flex items-center justify-center text-xl font-semibold'>
										{initials}
									</div>
								</div>
								<div>
									<h2 className='text-xl font-semibold'>{displayName}</h2>
									<p className='text-sm text-base-content/70'>
										{user.email ?? 'No email on file'}
									</p>
								</div>
							</div>

							<div className='flex gap-2'>
								<button
									type='button'
									className='btn btn-outline btn-sm'
									onClick={() => router.push('/qr')}>
									View my QRs
								</button>
							</div>
						</div>

						<div className='divider my-2' />

						{/* Basic details (read-only for now) */}
						<section className='space-y-4'>
							<h3 className='text-lg font-semibold'>Account details</h3>
							<div className='grid gap-4 md:grid-cols-2'>
								<div className='form-control'>
									<label className='label'>
										<span className='label-text'>Display name</span>
									</label>
									<input
										type='text'
										className='input input-bordered input-sm'
										defaultValue={displayName}
										disabled
									/>
									<label className='label'>
										<span className='label-text-alt text-base-content/60'>
											Editing coming soon – this is based on your account name.
										</span>
									</label>
								</div>

								<div className='form-control'>
									<label className='label'>
										<span className='label-text'>Email</span>
									</label>
									<input
										type='email'
										className='input input-bordered input-sm'
										defaultValue={user.email ?? ''}
										disabled
									/>
									<label className='label'>
										<span className='label-text-alt text-base-content/60'>
											Your primary sign-in email.
										</span>
									</label>
								</div>
							</div>
						</section>

						{/* Placeholder for future profile fields */}
						<section className='space-y-3'>
							<h3 className='text-lg font-semibold'>Profile info</h3>
							<p className='text-sm text-base-content/70'>
								In future you&apos;ll be able to add a short bio, location and
								how you use QR-Gen. For now, this section is a placeholder.
							</p>
						</section>

						<section className='space-y-3'>
							<h3 className='text-lg font-semibold'>Security</h3>
							<p className='text-sm text-base-content/70'>
								Password changes and two-step verification will be managed here
								in a later version. For now, use the sign-in provider&apos;s
								usual flow (email or Google) to manage your credentials.
							</p>
						</section>
					</div>
				</div>
			</div>
		</div>
	);
}
